UPDATE LIVROS_NOMES N SET N.CATALOGO_ID = (SELECT MIN(C.ID) FROM LIVROS_CATALOGO C WHERE C.TITULO COLLATE utf8mb4_0900_ai_ci = N.SUGESTAO_TITULO COLLATE utf8mb4_0900_ai_ci), N.ESTADO = 'OK', N.MOTIVO = 'Aceito em massa (certeza de 90% ou mais)' WHERE N.ESTADO = 'PENDENTE' AND GREATEST(COALESCE(N.CERTEZA, 0), COALESCE(N.CERTEZA_CLAUDE, 0)) >= 90 AND EXISTS (SELECT 1 FROM LIVROS_CATALOGO C WHERE C.TITULO COLLATE utf8mb4_0900_ai_ci = N.SUGESTAO_TITULO COLLATE utf8mb4_0900_ai_ci)